import click
from click.testing import CliRunner


def _make(order):
    without = click.option("--without-xyz", "enable_xyz", flag_value=False)
    with_ = click.option("--with-xyz", "enable_xyz", flag_value=True, default=True)

    @click.command("foo")
    def foo(enable_xyz):
        click.echo(f"enable_xyz = {enable_xyz!r}")

    decos = [without, with_] if order == "issue" else [with_, without]
    for d in decos:
        foo = d(foo)
    return foo


def test_diagnostics():
    print(click.__file__, getattr(click, "__version__", None))
    for order in ("issue", "swapped"):
        foo = click.command("foo")(lambda enable_xyz: None) if False else None
    @click.command("foo")
    @click.option("--without-xyz", "enable_xyz", flag_value=False)
    @click.option("--with-xyz", "enable_xyz", flag_value=True, default=True)
    def foo(enable_xyz):
        click.echo(f"enable_xyz = {enable_xyz!r}")

    info = [(p.opts, p.default, p.flag_value, p.is_bool_flag) for p in foo.params]
    r = CliRunner()
    res = {
        "default": r.invoke(foo, []).output.strip(),
        "with": r.invoke(foo, ["--with-xyz"]).output.strip(),
        "without": r.invoke(foo, ["--without-xyz"]).output.strip(),
        "with,without": r.invoke(foo, ["--with-xyz", "--without-xyz"]).output.strip(),
        "without,with": r.invoke(foo, ["--without-xyz", "--with-xyz"]).output.strip(),
    }
    assert False, (click.__file__, info, res)
